<script>
	$(document).ready(function () {
		var currentUrl = window.location.href;
		// Remove trailing slash if present for consistent matching (optional, but good practice)
		currentUrl = currentUrl.replace(/\/$/, "");


		// Video Hover Logic (Lazy Loading)
		$('.list-game[data-video-src]').hover(
			function () {
				var $this = $(this);
				var videoSrc = $this.data('video-src');
				if (videoSrc && !$this.find('video.hover-video').length) {
					// Create video element on hover
					var video = document.createElement('video');
					video.className = 'hover-video';
					video.loop = true;
					video.muted = true;
					video.playsInline = true;
					video.onerror = function() { $(this).remove(); };
					video.src = videoSrc;
					$this.prepend(video);
					video.play().catch(function () { $(video).remove(); });
				}
			},
			function () {
				// Remove video on mouse leave to free memory
				var video = $(this).find('video.hover-video');
				if (video.length) {
					video[0].pause();
					video.remove();
				}
			}
		);

		$('.sidebar-menu a').each(function () {
			var linkUrl = $(this).attr('href').replace(/\/$/, "");
			if (linkUrl === currentUrl) {
				$(this).addClass('active');
			}
		});

		// Prefetch links on hover for faster navigation (reduces flash effect)
		var prefetchedUrls = {};
		$('.sidebar-menu a, .navbar a').on('mouseenter', function() {
			var url = $(this).attr('href');
			if (url && !prefetchedUrls[url] && url.indexOf('https://noadsgames.org/') === 0) {
				prefetchedUrls[url] = true;
				var link = document.createElement('link');
				link.rel = 'prefetch';
				link.href = url;
				document.head.appendChild(link);
			}
		});
	});
</script>
</body>

</html>
